pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 2, 1e30);

        // Fund the contract through its payable fallback (one deposit -> depositsCount == 1).
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);
        assertEq(c.depositsCount(), 1);
        assertEq(address(c).balance, amount);

        // Owner (deployer = this contract) withdraws everything.
        c.withdrawAll();

        // General rule: withdrawAll drains the FULL ether balance of the contract.
        // The mutant withdraws depositsCount (== 1 wei) instead, leaving amount - 1 > 0.
        assertTrue(address(c).balance == 0, "withdrawAll must drain full balance");
    }
}

