pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        amount = bound(amount, 0, type(uint256).max / 2);

        // fund the contract through its fallback (increments depositsCount)
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund || amount == 0);

        // drive c through withdrawAll from the fuzzed actor
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // GENERAL RULE: withdrawAll may only succeed for the owner (draining balance
        // to 0); any failed attempt must leave balance and depositsCount untouched.
        assertTrue(
            ok
                ? (actor == c.owner() && address(c).balance == 0)
                : (address(c).balance == amount && c.depositsCount() == 1)
        );
    }
}

