pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, address(this).balance > 0 ? address(this).balance : 1);
        // fund the contract through its fallback
        vm.deal(address(this), amount);
        (bool s, ) = address(c).call{value: amount}("");
        assertTrue(s);
        uint256 cBal0 = address(c).balance;
        uint256 actorBal0 = actor.balance;
        vm.deal(actor, 1);
        vm.prank(actor);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        // General rule: a successful withdraw transfers exactly `amount` to the caller;
        // withdrawal succeeds only for the owner (who is the caller of a successful withdraw).
        assertTrue(
            ok
                ? (actor.balance == actorBal0 + amount && address(c).balance == cBal0 - amount)
                : (actor != address(this))
        );
    }
}

