		// non-owner calling withdrawAll must revert on P (onlyOwner)
		bytes memory payload = abi.encodeWithSignature("withdrawAll()");
		(bool ok, ) = address(c).call(payload);
		// on P: reverts for non-owner -> ok == false
		// on M: succeeds for non-owner -> ok == true
		assert(!ok);
	}

	receive() external payable {}
	fallback() external payable {}
}

